class Order {
  private _items: Item[];
  constructor(items: Item[]) { this._items = items; }
  total() { return this._items.reduce((s, i) => s + i.price, 0); }
}

class OrderArchiver {
  archive(order: Order) {
    for (const it of (order as any)._items) {
      if (!it.persistent) saveSnapshot(it);
    }
  }
}

// Version A
class Invoice {
  public items: LineItem[];
  constructor(items: LineItem[]) { this.items = items; }
}
class InvoicePdfA {
  print(inv: Invoice) {
    for (const it of inv.items) { this.draw(it.description, it.amount); }
  }
}

// Version B
class InvoiceB {
  private items: LineItem[];
  getPrintableItems() { return this.items.map(i => ({ description: i.description, amount: i.amount })); }
}
class InvoicePdfB {
  print(inv: InvoiceB) {
    for (const it of inv.getPrintableItems()) { this.draw(it.description, it.amount); }
  }
}
